def _pairs(d: str) -> list[tuple[float, float]]:
    nums = [float(tok) for tok in _NUM.findall(d)]
    if len(nums) % 2 != 0:
        raise ValueError("path coordinate count")
    return list(zip(nums[0::2], nums[1::2]))


def _crop_origin_and_size() -> tuple[int, int, int, int]:
    xs: list[float] = []
    ys: list[float] = []
    for _name, d in _SOURCE_SHAPES:
        for x, y in _pairs(d):
            xs.append(x)
            ys.append(y)
    min_x = math.floor(min(xs)) - HK_TIGHT_PAD
    min_y = math.floor(min(ys)) - HK_TIGHT_PAD
    max_x = math.ceil(max(xs)) + HK_TIGHT_PAD
    max_y = math.ceil(max(ys)) + HK_TIGHT_PAD
    return min_x, min_y, max_x - min_x, max_y - min_y


CROP_X, CROP_Y, CROP_W, CROP_H = _crop_origin_and_size()
CROP_ORIGIN = (CROP_X, CROP_Y)
DESIGN_SIZE = (CROP_W, CROP_H)


def _n(value: float) -> str:
    rounded = round(float(value), 1)
    if abs(rounded - round(rounded)) < 1e-9:
        return str(int(round(rounded)))
    return f"{rounded:.1f}"


def _translate(d: str) -> str:
    index = 0

    def repl(match: re.Match[str]) -> str:
        nonlocal index
        value = float(match.group(0))
        shifted = value - (CROP_X if index % 2 == 0 else CROP_Y)
        index += 1
        return _n(shifted)

    return _NUM.sub(repl, d)


def _label_box(d: str) -> tuple[float, float, float, float]:
    pts = _pairs(d)
    xs = [pt[0] for pt in pts]
    ys = [pt[1] for pt in pts]
    min_x = min(xs)
    min_y = min(ys)
    return (min_x, min_y, max(xs) - min_x, max(ys) - min_y)


@dataclass(frozen=True)
class Rect:
    slot: int
    x: int
    y: int
    w: int
    h: int


@dataclass(frozen=True)
class Shape:
    slot: int
    d: str
    label_box: tuple[float, float, float, float] | None


def _rects() -> tuple[Rect, ...]:
    rows: list[Rect] = []
    return tuple(rows)


def _shapes() -> tuple[Shape, ...]:
    if set(_SLOT_BY_NAME.values()) != set(range(128, 150)):
        raise RuntimeError("ISR-4 slot map is not 128..149 once")
    if {name for name, _d in _SOURCE_SHAPES} != set(_SLOT_BY_NAME):
        raise RuntimeError("ISR-4 trace names do not match the slot map")
    out: list[Shape] = []
    for name, d in _SOURCE_SHAPES:
        letters = set(re.findall(r"[A-Za-z]", d))
        if not letters <= {"M", "L", "Z"}:
            raise RuntimeError(f"{name} path is not a stored polyline")
        translated = _translate(d)
        out.append(Shape(slot=_SLOT_BY_NAME[name], d=translated, label_box=_label_box(translated)))
    return tuple(out)


RECTS: tuple[Rect, ...] = _rects()
SHAPES: tuple[Shape, ...] = _shapes()
